function communityOAuthCredentials(env, provider) {
  if (provider === "google") {
    return { clientId: String(env.GOOGLE_OAUTH_CLIENT_ID || "").trim(), clientSecret: String(env.GOOGLE_OAUTH_CLIENT_SECRET || "") };
  }
  if (provider === "facebook") {
    return { clientId: String(env.FACEBOOK_OAUTH_CLIENT_ID || "").trim(), clientSecret: String(env.FACEBOOK_OAUTH_CLIENT_SECRET || "") };
  }
  return { clientId: "", clientSecret: "" };
}
function communityOAuthReady(env, provider) {
  const credentials = communityOAuthCredentials(env, provider);
  return Boolean(credentials.clientId && credentials.clientSecret);
}
function communityOAuthCookieName(provider, part) {
  return "__Host-ai_oauth_" + provider + "_" + part;
}
function readCommunityOAuthCookie(request, name) {
  const prefix = name + "=";
  const cookies = request.headers.get("Cookie") || "";
  const entry = cookies.split(";").map((value) => value.trim()).find((value) => value.startsWith(prefix));
  return entry ? entry.slice(prefix.length) : "";
}
function communityOAuthCookie(provider, part, value, maxAge = COMMUNITY_OAUTH_STATE_TTL_SECONDS) {
  return communityOAuthCookieName(provider, part) + "=" + value +
    "; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=" + maxAge;
}
function communityOAuthRedirect(request, provider, result, extraCookies = []) {
  const destination = new URL("/", request.url);
  destination.searchParams.set("oauth", result);
  destination.searchParams.set("provider", provider);
  if (result !== "success" && result !== "cancelled" && result !== "email_missing" && result !== "unavailable") {
    destination.searchParams.set("oauth_error", result);
  }
  destination.hash = "cong-dong";
  const headers = new Headers({
    "Location": destination.toString(),
    "Cache-Control": "no-store, max-age=0",
    "Pragma": "no-cache",
    "Referrer-Policy": "no-referrer",
  });
  for (const cookie of extraCookies) headers.append("Set-Cookie", cookie);
  return new Response(null, { status: 302, headers });
}
function communityOAuthClearCookies(provider) {
  const cookies = [communityOAuthCookie(provider, "state", "", 0)];
  if (provider === "google") {
    cookies.push(communityOAuthCookie(provider, "verifier", "", 0));
    cookies.push(communityOAuthCookie(provider, "nonce", "", 0));
  }
  return cookies;
}

function validCommunityOAuthEmail(email) {
  const value = String(email || "").trim().toLowerCase();
  return value.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value) ? value : "";
}
async function validateGoogleOidcIdToken(idToken, clientId, expectedNonce) {
  if (typeof idToken !== "string" || idToken.length > 16384 || !expectedNonce) throw new Error("oidc_token_missing");
  const parts = idToken.split(".");
  if (parts.length !== 3 || parts.some((part) => !part || part.length > 12000)) throw new Error("oidc_jwt_malformed");
  const decodeBase64UrlJson = (part) => {
    const normalized = part.replace(/-/g, "+").replace(/_/g, "/");
    const padded = normalized + "=".repeat((4 - normalized.length % 4) % 4);
    const binary = atob(padded);
    const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
    return JSON.parse(new TextDecoder().decode(bytes));
  };
  const header = decodeBase64UrlJson(parts[0]);
  const claims = decodeBase64UrlJson(parts[1]);
  if (!header || header.alg !== "RS256" || typeof header.kid !== "string" || header.kid.length > 256) {
    throw new Error("oidc_header_invalid");
  }

  const discoveryResponse = await fetch("https://accounts.google.com/.well-known/openid-configuration", {
    headers: { "Accept": "application/json" },
    signal: AbortSignal.timeout(8000),
  });
  if (!discoveryResponse.ok) throw new Error("oidc_discovery_unavailable");
  const discovery = await discoveryResponse.json();
  if (discovery.issuer !== "https://accounts.google.com" ||
      typeof discovery.jwks_uri !== "string") throw new Error("oidc_discovery_invalid");
  const jwksUrl = new URL(discovery.jwks_uri);
  if (jwksUrl.protocol !== "https:" || jwksUrl.hostname !== "www.googleapis.com" ||
      jwksUrl.pathname !== "/oauth2/v3/certs") throw new Error("oidc_jwks_uri_invalid");

  const jwksResponse = await fetch(jwksUrl.toString(), {
    headers: { "Accept": "application/json" },
    signal: AbortSignal.timeout(8000),
  });
  if (!jwksResponse.ok) throw new Error("oidc_jwks_unavailable");
  const jwks = await jwksResponse.json();
  const jwk = Array.isArray(jwks.keys)
    ? jwks.keys.find((key) => key && key.kid === header.kid && key.kty === "RSA" &&
        key.alg === "RS256" && (!key.use || key.use === "sig"))
    : null;
  if (!jwk) throw new Error("oidc_signing_key_not_found");
  const publicKey = await crypto.subtle.importKey(
    "jwk",
    jwk,
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false,
    ["verify"]
  );
  const signatureText = parts[2].replace(/-/g, "+").replace(/_/g, "/");
  const signaturePadded = signatureText + "=".repeat((4 - signatureText.length % 4) % 4);
  const signatureBinary = atob(signaturePadded);
  const signature = Uint8Array.from(signatureBinary, (character) => character.charCodeAt(0));
  const signedBytes = new TextEncoder().encode(parts[0] + "." + parts[1]);
  const validSignature = await crypto.subtle.verify("RSASSA-PKCS1-v1_5", publicKey, signature, signedBytes);
  if (!validSignature) throw new Error("oidc_signature_invalid");

  const now = Math.floor(Date.now() / 1000);
  const audiences = Array.isArray(claims.aud) ? claims.aud : [claims.aud];
  if (!["https://accounts.google.com", "accounts.google.com"].includes(claims.iss) ||
      !audiences.includes(clientId) ||
      (audiences.length > 1 && claims.azp !== clientId) ||
      (claims.azp && claims.azp !== clientId) ||
      !Number.isInteger(claims.exp) || claims.exp <= now ||
      (claims.nbf !== undefined && (!Number.isInteger(claims.nbf) || claims.nbf > now + 60)) ||
      !Number.isInteger(claims.iat) || claims.iat > now + 60 ||
      now - claims.iat > 60 * 60 ||
      claims.exp <= claims.iat ||
      typeof claims.sub !== "string" || !/^[\x21-\x7E]{1,255}$/.test(claims.sub) ||
      claims.nonce !== expectedNonce ||
      claims.email_verified !== true) {
    throw new Error("oidc_claims_invalid");
  }
  const email = validCommunityOAuthEmail(claims.email);
  if (!email) throw new Error("oidc_email_invalid");
  return {
    sub: claims.sub,
    email,
    name: String(claims.name || claims.given_name || "").trim().slice(0, 40),
  };
}


async function beginCommunityOAuth(request, env, provider, db) {
  const requestUrl = new URL(request.url);
  if (requestUrl.origin !== COMMUNITY_OAUTH_STAGING_ORIGIN) {
    return communityJson({ error: "Đăng nhập mạng xã hội hiện chưa được bật." }, 404, request);
  }
  const credentials = communityOAuthCredentials(env, provider);
  if (!credentials.clientId || !credentials.clientSecret) {
    return communityJson({ error: "Nhà cung cấp đăng nhập chưa được cấu hình.", code: "OAUTH_NOT_CONFIGURED" }, 503, request);
  }
  const ip = request.headers.get("CF-Connecting-IP") || "unknown";
  const ipHash = await sha256Base64Url(ip);
  if (!await communityRateLimit(db, "oauth-start:" + provider + ":" + ipHash, 10, 15 * 60 * 1000)) {
    return communityJson({ error: "Bạn đã bắt đầu đăng nhập quá nhiều lần. Vui lòng thử lại sau." }, 429, request);
  }

  const state = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
  const redirectUri = COMMUNITY_OAUTH_STAGING_ORIGIN + "/api/community/oauth/" + provider + "/callback";
  const headers = new Headers({
    "Cache-Control": "no-store, max-age=0",
    "Pragma": "no-cache",
    "Referrer-Policy": "no-referrer",
  });
  let authorizationUrl;
  headers.append("Set-Cookie", communityOAuthCookie(provider, "state", state));

  if (provider === "google") {
    const verifier = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
    const challenge = await sha256Base64Url(verifier);
    const nonce = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
    headers.append("Set-Cookie", communityOAuthCookie(provider, "verifier", verifier));
    headers.append("Set-Cookie", communityOAuthCookie(provider, "nonce", nonce));
    authorizationUrl = new URL("https://accounts.google.com/o/oauth2/v2/auth");
    authorizationUrl.search = new URLSearchParams({
      client_id: credentials.clientId,
      redirect_uri: redirectUri,
      response_type: "code",
      scope: "openid email profile",
      state,
      nonce,
      code_challenge: challenge,
      code_challenge_method: "S256",
      prompt: "select_account",
    }).toString();
  } else {
    authorizationUrl = new URL("https://www.facebook.com/v26.0/dialog/oauth");
    authorizationUrl.search = new URLSearchParams({
      client_id: credentials.clientId,
      redirect_uri: redirectUri,
      response_type: "code",
      scope: "email,public_profile",
      state,
    }).toString();
  }
  headers.set("Location", authorizationUrl.toString());
  return new Response(null, { status: 302, headers });
}

async function communityOAuthMember(db, provider, providerUserId, email, displayName) {
  const now = new Date().toISOString();
  const linkedSql = "SELECT m.id, m.username, m.email, m.display_name, m.created_at " +
    "FROM community_oauth_accounts a JOIN community_members m ON m.id = a.member_id " +
    "WHERE a.provider = ? AND a.provider_user_id = ? LIMIT 1";
  let linked = await db.prepare(linkedSql).bind(provider, providerUserId).first();
  if (linked) return linked;

  const byEmailSql = "SELECT id, username, email, display_name, email_verified_at, created_at " +
    "FROM community_members WHERE email = ? LIMIT 1";
  // Facebook's /me email field is not an explicit verified-email claim. Never use it
  // to find, verify, or take over an existing email/password account. Keep the
  // provider identity separate until an authenticated account-link flow exists.
  const memberEmail = provider === "facebook"
    ? "facebook-" + await sha256Base64Url(providerUserId) + "@social.invalid"
    : email;
  let member = await db.prepare(byEmailSql).bind(memberEmail).first();
  if (member) {
    // Only Google's explicit email_verified claim permits email-based account linking.
    if (provider === "google" && !member.email_verified_at) {
      await db.prepare("UPDATE community_members SET email_verified_at = ? WHERE id = ? AND email_verified_at IS NULL")
        .bind(now, member.id).run();
      member.email_verified_at = now;
    }
  } else {
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const inaccessiblePassword = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
    const passwordHash = await hashCommunityPassword(inaccessiblePassword, salt);
    const baseUsername = (memberEmail.split("@")[0] || "member").toLowerCase()
      .replace(/[^a-z0-9_]/g, "_").replace(/_+/g, "_").replace(/^_+|_+$/g, "") || "member";
    const verifiedAt = provider === "google" ? now : null;
    let created = false;
    for (let attempt = 0; attempt < 8 && !created; attempt += 1) {
      const suffix = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(5))).slice(0, 5).toLowerCase();
      const username = baseUsername.slice(0, 18) + "_" + suffix;
      const memberId = crypto.randomUUID();
      try {
        await db.prepare("INSERT INTO community_members " +
          "(id, username, email, display_name, password_salt, password_hash, created_at, email_verified_at) " +
          "VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
          .bind(memberId, username, memberEmail, displayName.slice(0, 40), bytesToBase64Url(salt), passwordHash, now, verifiedAt).run();
        member = { id: memberId, username, email: memberEmail, display_name: displayName.slice(0, 40), email_verified_at: verifiedAt, created_at: now };
        created = true;
      } catch (error) {
        member = await db.prepare(byEmailSql).bind(memberEmail).first();
        if (member) {
          if (provider === "google" && !member.email_verified_at) {
            await db.prepare("UPDATE community_members SET email_verified_at = ? WHERE id = ? AND email_verified_at IS NULL")
              .bind(now, member.id).run();
            member.email_verified_at = now;
          }
          created = true;
        } else if (!/unique|constraint/i.test(String(error?.message || error))) {
          throw error;
        }
      }
    }
    if (!member) throw new Error("oauth_member_create_failed");
  }

  await db.prepare("INSERT INTO community_oauth_accounts " +
    "(provider, provider_user_id, member_id, email, created_at) VALUES (?, ?, ?, ?, ?) " +
    "ON CONFLICT(provider, provider_user_id) DO NOTHING")
    .bind(provider, providerUserId, member.id, email, now).run();

  linked = await db.prepare(linkedSql).bind(provider, providerUserId).first();
  if (!linked) throw new Error("oauth_identity_link_failed");
  return linked;
}

async function completeCommunityOAuth(request, env, provider, db) {
  const requestUrl = new URL(request.url);
  const clearCookies = communityOAuthClearCookies(provider);
  const fail = (reason) => communityOAuthRedirect(request, provider, reason, clearCookies);
  if (requestUrl.origin !== COMMUNITY_OAUTH_STAGING_ORIGIN) {
    return communityJson({ error: "Callback đăng nhập không hợp lệ." }, 404, request);
  }
  // Bound callback processing before any provider network request or D1 account mutation.
  const callbackIp = request.headers.get("CF-Connecting-IP") || "unknown";
  const callbackIpHash = await sha256Base64Url(callbackIp);
  if (!await communityRateLimit(db, "oauth-callback:" + provider + ":" + callbackIpHash, 30, 15 * 60 * 1000)) {
    return fail("OAUTH_CALLBACK_RATE_LIMITED");
  }
  const state = String(requestUrl.searchParams.get("state") || "");
  const storedState = readCommunityOAuthCookie(request, communityOAuthCookieName(provider, "state"));
  if (!state || state.length > 128 || !storedState || state !== storedState) return fail("OAUTH_STATE_INVALID");
  if (requestUrl.searchParams.has("error")) return fail("cancelled");
  const code = String(requestUrl.searchParams.get("code") || "");
  if (!code || code.length > 2048) return fail("OAUTH_CODE_MISSING");
  if (!communityOAuthReady(env, provider)) return fail("unavailable");

  let stage = "OAUTH_TOKEN_EXCHANGE_FAILED";
  try {
    const credentials = communityOAuthCredentials(env, provider);
    const redirectUri = COMMUNITY_OAUTH_STAGING_ORIGIN + "/api/community/oauth/" + provider + "/callback";
    const tokenUrl = provider === "google"
      ? "https://oauth2.googleapis.com/token"
      : "https://graph.facebook.com/v26.0/oauth/access_token";
    const tokenBody = new URLSearchParams({
      client_id: credentials.clientId,
      client_secret: credentials.clientSecret,
      code,
      redirect_uri: redirectUri,
      grant_type: "authorization_code",
    });
    if (provider === "google") {
      const verifier = readCommunityOAuthCookie(request, communityOAuthCookieName(provider, "verifier"));
      if (!verifier || verifier.length < 43 || verifier.length > 128) return fail("OAUTH_VERIFIER_MISSING");
      tokenBody.set("code_verifier", verifier);
    }
    let tokenResponse;
    try {
      tokenResponse = await fetch(tokenUrl, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: tokenBody.toString(),
        signal: AbortSignal.timeout(10000),
      });
    } catch (_networkError) {
      // Probe only the public Google token endpoint with a credential-free GET.
      // A non-2xx HTTP response still proves DNS/TLS/egress reached Google.
      // Never log exception messages, request bodies, OAuth codes, cookies or credentials.
      const errorName = typeof _networkError?.name === "string" ? _networkError.name : "";
      const errorClass = ["AbortError", "TimeoutError", "TypeError", "Error"].includes(errorName)
        ? errorName
        : "Other";
      const timedOut = errorName === "TimeoutError" || errorName === "AbortError";
      let endpointReachable = false;
      let probeStatus = 0;
      if (provider === "google") {
        try {
          const probe = await fetch("https://oauth2.googleapis.com/token", {
            method: "GET",
                signal: AbortSignal.timeout(5000),
          });
          endpointReachable = true;
          probeStatus = probe.status;
        } catch (_probeError) {
          endpointReachable = false;
        }
      }
      console.warn("[oauth] token_exchange_transport_failure", {
        provider,
        errorClass,
        endpointReachable,
        probeStatus,
      });
      if (timedOut) return fail("OAUTH_TOKEN_TIMEOUT");
      return fail(endpointReachable ? "OAUTH_TOKEN_REQUEST_FAILED" : "OAUTH_GOOGLE_ENDPOINT_UNREACHABLE");
    }
    let tokenPayload;
    try {
      tokenPayload = await tokenResponse.json();
    } catch (_parseError) {
      return fail("OAUTH_TOKEN_RESPONSE_INVALID");
    }
    if (!tokenResponse.ok || typeof tokenPayload.access_token !== "string" || tokenPayload.access_token.length > 4096) {
      // Expose only a strictly sanitized provider error identifier, never its description or payload.
      const googleError = provider === "google" ? String(tokenPayload.error || "") : "";
      const safeGoogleError = /^[a-z][a-z0-9_]{1,63}$/.test(googleError)
        ? "OAUTH_GOOGLE_" + googleError.toUpperCase()
        : "OAUTH_TOKEN_EXCHANGE_FAILED";
      return fail(safeGoogleError);
    }

    stage = "OAUTH_USERINFO_FAILED";
    let providerUserId = "";
    let email = "";
    let displayName = "";
    if (provider === "google") {
      const expectedNonce = readCommunityOAuthCookie(request, communityOAuthCookieName(provider, "nonce"));
      if (!expectedNonce || expectedNonce.length > 128) return fail("OAUTH_NONCE_MISSING");
      if (typeof tokenPayload.id_token !== "string") return fail("OAUTH_ID_TOKEN_MISSING");
      const identity = await validateGoogleOidcIdToken(tokenPayload.id_token, credentials.clientId, expectedNonce);
      providerUserId = identity.sub;
      email = identity.email;
      displayName = identity.name;
    } else {
      const userResponse = await fetch("https://graph.facebook.com/v26.0/me?fields=id%2Cname%2Cemail", {
        headers: { "Authorization": "Bearer " + tokenPayload.access_token },
        signal: AbortSignal.timeout(10000),
      });
      const user = await userResponse.json();
      if (!userResponse.ok) return fail("OAUTH_USERINFO_FAILED");
      providerUserId = String(user.id || "");
      email = validCommunityOAuthEmail(user.email);
      displayName = String(user.name || "").trim();
      // Facebook can omit email when the user has no confirmed address or has not granted the email permission.
      if (!email) return fail("email_missing");
    }
    if (!providerUserId || providerUserId.length > 255 || !email) return fail("OAUTH_PROFILE_INVALID");
    if (displayName.length < 2) displayName = email.split("@")[0];
    displayName = displayName.slice(0, 40);

    stage = "OAUTH_MEMBER_PERSIST_FAILED";
    const member = await communityOAuthMember(db, provider, providerUserId, email, displayName);
    const sessionToken = await createCommunitySession(db, member.id);
    const response = communityOAuthRedirect(request, provider, "success", clearCookies);
    response.headers.append("Set-Cookie", communityCookie(sessionToken));
    return response;
  } catch (_error) {
    // Emit only fixed stage codes. Never log secrets, tokens, cookies, email or provider payloads.
    if (_error?.message === "oauth_account_link_required") return fail("OAUTH_ACCOUNT_LINK_REQUIRED");
    return fail(stage);
  }
}

async function handleCommunityApi(request, env) {
  const origin = request.headers.get("Origin");
  if (origin && !COMMUNITY_ALLOWED_ORIGINS.has(origin)) return communityJson({ error: "Nguồn yêu cầu không được phép." }, 403, request);
  if (request.method === "OPTIONS") return communityJson({ ok: true }, 200, request);
  const url = new URL(request.url);
  const route = url.pathname.replace(/^\/api\/community\/?/, "");

  // Fixed-host, credential-free egress diagnostics for the staging Worker only.
  // Never accept a caller-supplied URL or return raw network exception messages.
  if (route === "oauth/egress-check" && request.method === "GET") {
    if (url.origin !== COMMUNITY_OAUTH_STAGING_ORIGIN) {
      return communityJson({ error: "Not found" }, 404, request);
    }
    const targets = [
      ["google_token", "https://oauth2.googleapis.com/token"],
      ["google_userinfo", "https://openidconnect.googleapis.com/v1/userinfo"],
      ["google_certs", "https://www.googleapis.com/oauth2/v3/certs"],
      ["google_accounts", "https://accounts.google.com/.well-known/openid-configuration"],
      ["egress_control", "https://www.cloudflare.com/cdn-cgi/trace"],
    ];
    const runtime = {
      fetch_available: typeof fetch === "function",
      abort_signal_timeout_available: typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function",
      abort_controller_available: typeof AbortController === "function",
      set_timeout_available: typeof setTimeout === "function",
    };
    const results = await Promise.all(targets.map(async ([name, target]) => {
      let requestConstructed = false;
      try {
        // Keep the baseline probe minimal to isolate outbound fetch reachability.
        const request = new Request(target);
        requestConstructed = true;
        const response = await fetch(request);
        return { name, request_constructed: requestConstructed, reachable: true, status: response.status };
      } catch (error) {
        const errorName = typeof error?.name === "string" ? error.name : "";
        const message = typeof error?.message === "string" ? error.message.toLowerCase() : "";
        const causeCode = typeof error?.cause?.code === "string" && /^[A-Z0-9_]{2,48}$/.test(error.cause.code)
          ? error.cause.code
          : null;
        const safeErrorHint = /redirect/.test(message) ? "redirect"
          : /network|connection|fetch failed/.test(message) ? "network"
          : /url|scheme|protocol/.test(message) ? "url"
          : /request|input/.test(message) ? "request"
          : /blocked|disallowed|forbidden/.test(message) ? "policy"
          : errorName === "TypeError" ? "unclassified_typeerror"
          : "other";
        const errorClass = ["AbortError", "TimeoutError", "TypeError", "Error"].includes(errorName)
          ? errorName
          : "Other";
        return { name, request_constructed: requestConstructed, reachable: false, errorClass, causeCode, safeErrorHint };
      }
    }));

    // Safely isolate the RequestInit options used by the real Google token exchange.
    // The POST carries only an intentionally incomplete dummy grant and never includes
    // an OAuth code, client ID/secret, cookies, tokens or personal information.
    const tokenEndpoint = "https://oauth2.googleapis.com/token";
    const dummyForm = new URLSearchParams({ grant_type: "authorization_code" }).toString();
    const postHeaders = { "Content-Type": "application/x-www-form-urlencoded" };
    const timeoutSignal = () => runtime.abort_signal_timeout_available ? AbortSignal.timeout(5000) : undefined;
    const optionAttempts = [
      ["get_redirect_only", { method: "GET", redirect: "error" }],
      ["get_timeout_only", { method: "GET", signal: timeoutSignal() }],
      ["get_redirect_and_timeout", { method: "GET", redirect: "error", signal: timeoutSignal() }],
      ["post_form_minimal", { method: "POST", headers: postHeaders, body: dummyForm }],
      ["post_form_redirect", { method: "POST", headers: postHeaders, body: dummyForm, redirect: "error" }],
      ["post_form_timeout", { method: "POST", headers: postHeaders, body: dummyForm, signal: timeoutSignal() }],
      ["post_form_full_options", { method: "POST", headers: postHeaders, body: dummyForm, redirect: "error", signal: timeoutSignal() }],
    ];
    const requestOptionsChecks = await Promise.all(optionAttempts.map(async ([name, init]) => {
      try {
        const response = await fetch(tokenEndpoint, init);
        return { name, reachable: true, status: response.status };
      } catch (error) {
        const errorName = typeof error?.name === "string" ? error.name : "";
        const message = typeof error?.message === "string" ? error.message.toLowerCase() : "";
        const causeCode = typeof error?.cause?.code === "string" && /^[A-Z0-9_]{2,48}$/.test(error.cause.code)
          ? error.cause.code
          : null;
        const safeErrorHint = /redirect/.test(message) ? "redirect"
          : /network|connection|fetch failed/.test(message) ? "network"
          : /url|scheme|protocol/.test(message) ? "url"
          : /request|input|body/.test(message) ? "request"
          : /blocked|disallowed|forbidden/.test(message) ? "policy"
          : errorName === "TypeError" ? "unclassified_typeerror"
          : "other";
        const errorClass = ["AbortError", "TimeoutError", "TypeError", "Error"].includes(errorName)
          ? errorName
          : "Other";
        return { name, reachable: false, errorClass, causeCode, safeErrorHint };
      }
    }));
    return communityJson({
      environment: "staging",
      checked_at: new Date().toISOString(),
      runtime,
      results,
      request_options_checks: requestOptionsChecks,
    }, 200, request);
  }

  if (route === "oauth/providers" && request.method === "GET") {
    return communityJson({
      google: communityOAuthReady(env, "google"),
      facebook: communityOAuthReady(env, "facebook"),
    }, 200, request);
  }

  const oauthRoute = route.match(/^oauth\/(google|facebook)\/(start|callback)$/);
  if (oauthRoute && request.method === "GET") {
    if (!env.DB || typeof env.DB.prepare !== "function") {
      return communityJson({ error: "Cộng đồng chưa sẵn sàng trên staging." }, 503, request);
    }
    return oauthRoute[2] === "start"
      ? beginCommunityOAuth(request, env, oauthRoute[1], env.DB)
      : completeCommunityOAuth(request, env, oauthRoute[1], env.DB);
  }

  if (!env.DB || typeof env.DB.prepare !== "function") {
    return communityJson({ error: "Cộng đồng chưa được cấu hình cơ sở dữ liệu. Quản trị viên cần hoàn tất thiết lập D1." }, 503, request);
  }
  const db = env.DB;
  const ip = request.headers.get("CF-Connecting-IP") || "unknown";
  const now = new Date().toISOString();

  try {
    if (route === "register" && request.method === "POST") {
      const parsed = await readJsonPayload(request);
      if (!parsed.ok) return communityJson({ error: parsed.error }, parsed.status, request);
      const payload = parsed.value;
      const username = String(payload.username || "").trim().toLowerCase();
      const displayName = String(payload.displayName || payload.username || "").trim();
      const email = String(payload.email || "").trim().toLowerCase();
      const password = String(payload.password || "");
      if (!/^[a-z0-9_]{3,24}$/.test(username)) return communityJson({ error: "Tên thành viên cần 3–24 ký tự: chữ thường, số hoặc dấu gạch dưới." }, 400, request);
      if (displayName.length < 2 || displayName.length > 40) return communityJson({ error: "Tên hiển thị cần từ 2 đến 40 ký tự." }, 400, request);
      if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return communityJson({ error: "Vui lòng nhập email hợp lệ." }, 400, request);
      if (password.length < 10 || password.length > 128) return communityJson({ error: "Mật khẩu cần từ 10 đến 128 ký tự." }, 400, request);
      const relayUrl = String(env.COMMUNITY_EMAIL_RELAY_URL || "").trim();
      const relaySecret = String(env.COMMUNITY_EMAIL_RELAY_SECRET || "");
      if (!relayUrl || relaySecret.length < 32) {
        return communityJson({ error: "Dịch vụ xác nhận email chưa được cấu hình. Tài khoản chưa được tạo; vui lòng thử lại sau.", code: "EMAIL_RELAY_NOT_CONFIGURED" }, 503, request);
      }
      const ipHash = await sha256Base64Url(ip);
      if (!await communityRateLimit(db, "register:" + ipHash, 5, 60 * 60 * 1000)) return communityJson({ error: "Bạn đã thử đăng ký quá nhiều lần. Vui lòng thử lại sau một giờ." }, 429, request);
      const salt = crypto.getRandomValues(new Uint8Array(16));
      const passwordHash = await hashCommunityPassword(password, salt);
      const memberId = crypto.randomUUID();
      let memberCreated = false;
      try {
        await db.prepare("INSERT INTO community_members (id, username, email, display_name, password_salt, password_hash, created_at, email_verified_at) VALUES (?, ?, ?, ?, ?, ?, ?, NULL)")
          .bind(memberId, username, email, displayName, bytesToBase64Url(salt), passwordHash, now).run();
        memberCreated = true;
        const token = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
        const tokenHash = await sha256Base64Url(token);
        const expiresAt = new Date(Date.now() + 30 * 60 * 1000).toISOString();
        await db.prepare("INSERT INTO community_email_verification_tokens (token_hash, member_id, created_at, expires_at) VALUES (?, ?, ?, ?)")
          .bind(tokenHash, memberId, now, expiresAt).run();
        const sent = await sendCommunityVerificationEmail(env, email, token, url.origin);
        if (!sent) {
          await db.batch([
            db.prepare("DELETE FROM community_email_verification_tokens WHERE member_id = ?").bind(memberId),
            db.prepare("DELETE FROM community_members WHERE id = ?").bind(memberId),
          ]);
          return communityJson({ error: "Không thể gửi email xác nhận. Tài khoản chưa được tạo; vui lòng thử lại sau.", code: "EMAIL_RELAY_FAILED" }, 503, request);
        }
      } catch (error) {
        if (memberCreated) {
          try {
            await db.batch([
              db.prepare("DELETE FROM community_email_verification_tokens WHERE member_id = ?").bind(memberId),
              db.prepare("DELETE FROM community_members WHERE id = ?").bind(memberId),
            ]);
          } catch (_cleanupError) { /* Keep the original failure; never log credentials. */ }
        }
        if (/unique|constraint/i.test(String(error?.message || error))) {
          return communityJson({ error: "Email hoặc tên thành viên đã được sử dụng." }, 409, request);
        }
        throw error;
      }
      return communityJson({
        pendingVerification: true,
        message: "Tài khoản đã được tạo nhưng chưa kích hoạt. Hãy kiểm tra hộp thư đến và thư rác để xác nhận email trong vòng 30 phút.",
      }, 202, request);
    }

    if (route === "verify-email" && request.method === "POST") {
      const parsed = await readJsonPayload(request);
      if (!parsed.ok) return communityJson({ error: "Liên kết xác nhận không hợp lệ hoặc đã hết hạn." }, 400, request);
      const token = String(parsed.value.token || "").trim();
      if (!/^[A-Za-z0-9_-]{32,80}$/.test(token)) {
        return communityJson({ error: "Liên kết xác nhận không hợp lệ hoặc đã hết hạn." }, 400, request);
      }
      const tokenHash = await sha256Base64Url(token);
      // Atomically claim and consume a valid token before updating the member.
      // Concurrent requests can no longer both read the same token and both succeed.
      const claimed = await db.prepare("DELETE FROM community_email_verification_tokens WHERE token_hash = ? AND expires_at > ? RETURNING member_id").bind(tokenHash, now).first();
      if (!claimed) {
        // Remove an expired token if it is still present; invalid/replayed tokens fail closed.
        await db.prepare("DELETE FROM community_email_verification_tokens WHERE token_hash = ? AND expires_at <= ?").bind(tokenHash, now).run();
        return communityJson({ error: "Liên kết xác nhận không hợp lệ hoặc đã hết hạn." }, 400, request);
      }
      await db.prepare("UPDATE community_members SET email_verified_at = ? WHERE id = ? AND email_verified_at IS NULL").bind(now, claimed.member_id).run();
      return communityJson({ ok: true, message: "Email đã được xác nhận. Bạn có thể đăng nhập." }, 200, request);
    }

    if (route === "resend-verification" && request.method === "POST") {
      const genericMessage = "Nếu email thuộc tài khoản đang chờ xác nhận, hệ thống sẽ gửi hướng dẫn xác nhận khi dịch vụ sẵn sàng.";
      const parsed = await readJsonPayload(request);
      if (!parsed.ok) return communityJson({ ok: true, message: genericMessage }, 200, request);
      const email = String(parsed.value.email || "").trim().toLowerCase();
      if (!email || email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        return communityJson({ ok: true, message: genericMessage }, 200, request);
      }
      const ipHash = await sha256Base64Url(ip);
      const emailHash = await sha256Base64Url(email);
      if (!await communityRateLimit(db, "resend-ip:" + ipHash, 5, 60 * 60 * 1000) ||
          !await communityRateLimit(db, "resend-email:" + emailHash, 3, 60 * 60 * 1000)) {
        return communityJson({ ok: true, message: genericMessage }, 200, request);
      }
      const relayUrl = String(env.COMMUNITY_EMAIL_RELAY_URL || "").trim();
      const relaySecret = String(env.COMMUNITY_EMAIL_RELAY_SECRET || "");
      if (relayUrl && relaySecret.length >= 32) {
        const member = await db.prepare("SELECT id, email_verified_at FROM community_members WHERE email = ? LIMIT 1").bind(email).first();
        if (member && !member.email_verified_at) {
          const token = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
          const tokenHash = await sha256Base64Url(token);
          const createdAt = new Date().toISOString();
          const expiresAt = new Date(Date.now() + 30 * 60 * 1000).toISOString();
          // Keep the previous token until the replacement email is confirmed sent.
          await db.prepare("INSERT INTO community_email_verification_tokens (token_hash, member_id, created_at, expires_at) VALUES (?, ?, ?, ?)")
            .bind(tokenHash, member.id, createdAt, expiresAt).run();
          if (!await sendCommunityVerificationEmail(env, email, token, url.origin)) {
            await db.prepare("DELETE FROM community_email_verification_tokens WHERE token_hash = ?").bind(tokenHash).run();
          } else {
            await db.prepare("DELETE FROM community_email_verification_tokens WHERE member_id = ? AND token_hash <> ?")
              .bind(member.id, tokenHash).run();
          }
        }
      }
      return communityJson({ ok: true, message: genericMessage }, 200, request);
    }


    if (route === "request-password-reset" && request.method === "POST") {
      const genericMessage = "Nếu email thuộc tài khoản đã xác nhận, hệ thống sẽ gửi liên kết đặt lại mật khẩu nếu dịch vụ sẵn sàng.";
      const parsed = await readJsonPayload(request);
      if (!parsed.ok) return communityJson({ ok: true, message: genericMessage }, 200, request);
      const email = String(parsed.value.email || "").trim().toLowerCase();
      if (!email || email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        return communityJson({ ok: true, message: genericMessage }, 200, request);
      }
      const ipHash = await sha256Base64Url(ip);
      const emailHash = await sha256Base64Url(email);
      if (!await communityRateLimit(db, "password-reset-ip:" + ipHash, 5, 60 * 60 * 1000) ||
          !await communityRateLimit(db, "password-reset-email:" + emailHash, 3, 60 * 60 * 1000)) {
        return communityJson({ ok: true, message: genericMessage }, 200, request);
      }
      const relayUrl = String(env.COMMUNITY_EMAIL_RELAY_URL || "").trim();
      const relaySecret = String(env.COMMUNITY_EMAIL_RELAY_SECRET || "");
      if (relayUrl && relaySecret.length >= 32) {
        const member = await db.prepare("SELECT id, email_verified_at FROM community_members WHERE email = ? LIMIT 1").bind(email).first();
        if (member && member.email_verified_at) {
          const token = bytesToBase64Url(crypto.getRandomValues(new Uint8Array(32)));
          const tokenHash = await sha256Base64Url(token);
          const createdAt = new Date().toISOString();
          const expiresAt = new Date(Date.now() + 30 * 60 * 1000).toISOString();
          // Preserve the last delivered token until a replacement email is confirmed sent.
          await db.prepare("INSERT INTO community_password_reset_tokens (token_hash, member_id, created_at, expires_at) VALUES (?, ?, ?, ?)")
            .bind(tokenHash, member.id, createdAt, expiresAt).run();
          if (!await sendCommunityPasswordResetEmail(env, email, token, url.origin)) {
            await db.prepare("DELETE FROM community_password_reset_tokens WHERE token_hash = ?").bind(tokenHash).run();
          } else {
            await db.prepare("DELETE FROM community_password_reset_tokens WHERE member_id = ? AND token_hash <> ?")
              .bind(member.id, tokenHash).run();
          }
        }
      }
      return communityJson({ ok: true, message: genericMessage }, 200, request);
    }

    if (route === "reset-password" && request.method === "POST") {
      const parsed = await readJsonPayload(request);
      if (!parsed.ok) return communityJson({ error: "Liên kết đặt lại mật khẩu không hợp lệ hoặc đã hết hạn." }, 400, request);
      const token = String(parsed.value.token || "").trim();
      const password = String(parsed.value.password || "");
      if (password.length < 10 || password.length > 128) {
        return communityJson({ error: "Mật khẩu mới cần từ 10 đến 128 ký tự." }, 400, request);
      }
      const ipHash = await sha256Base64Url(ip);
      if (!await communityRateLimit(db, "password-reset-submit-ip:" + ipHash, 10, 15 * 60 * 1000)) {
        return communityJson({ error: "Bạn đã thử quá nhiều lần. Hãy yêu cầu liên kết đặt lại mật khẩu mới sau." }, 429, request);
      }
      if (!/^[A-Za-z0-9_-]{32,80}$/.test(token)) {
        return communityJson({ error: "Liên kết đặt lại mật khẩu không hợp lệ hoặc đã hết hạn." }, 400, request);
      }
      const tokenHash = await sha256Base64Url(token);
      // Atomic token claim: concurrent submissions cannot both claim the same token.
      const claimed = await db.prepare("DELETE FROM community_password_reset_tokens WHERE token_hash = ? AND expires_at > ? RETURNING member_id")
        .bind(tokenHash, now).first();
      if (!claimed) {
        await db.prepare("DELETE FROM community_password_reset_tokens WHERE token_hash = ? AND expires_at <= ?")
          .bind(tokenHash, now).run();
        return communityJson({ error: "Liên kết đặt lại mật khẩu không hợp lệ hoặc đã hết hạn." }, 400, request);
      }
      const salt = crypto.getRandomValues(new Uint8Array(16));
      const passwordHash = await hashCommunityPassword(password, salt);
      const updated = await db.prepare("UPDATE community_members SET password_salt = ?, password_hash = ? WHERE id = ?")
        .bind(bytesToBase64Url(salt), passwordHash, claimed.member_id).run();
      if (Number(updated?.meta?.changes || 0) !== 1) {
        return communityJson({ error: "Không thể cập nhật mật khẩu. Hãy yêu cầu liên kết mới." }, 400, request);
      }
      await db.prepare("DELETE FROM community_sessions WHERE member_id = ?").bind(claimed.member_id).run();
      return communityJson({ ok: true, message: "Mật khẩu đã được cập nhật. Bạn có thể đăng nhập bằng mật khẩu mới." }, 200, request);
    }

    if (route === "login" && request.method === "POST") {
      const parsed = await readJsonPayload(request);
      if (!parsed.ok) return communityJson({ error: parsed.error }, parsed.status, request);
      const payload = parsed.value;
      const email = String(payload.email || "").trim().toLowerCase();
      const password = String(payload.password || "");
      if (!email || email.length > 254 || !password || password.length > 128) return communityJson({ error: "Vui lòng kiểm tra email và mật khẩu." }, 400, request);
      const ipHash = await sha256Base64Url(ip);
      const emailHash = await sha256Base64Url(email);
      if (!await communityRateLimit(db, "login-ip:" + ipHash, 20, 15 * 60 * 1000) ||
          !await communityRateLimit(db, "login-account:" + emailHash + ":" + ipHash, 8, 15 * 60 * 1000)) {
        return communityJson({ error: "Bạn đăng nhập quá nhiều lần. Vui lòng thử lại sau ít phút." }, 429, request);
      }
      const row = await db.prepare("SELECT id, username, email, display_name, password_salt, password_hash, created_at, email_verified_at FROM community_members WHERE email = ? LIMIT 1").bind(email).first();
      let valid = false;
      if (row) {
        try { valid = (await hashCommunityPassword(password, base64UrlToBytes(row.password_salt))) === row.password_hash; } catch (_error) { valid = false; }
      }
      if (!valid) return communityJson({ error: "Email hoặc mật khẩu chưa chính xác." }, 401, request);
      if (!row.email_verified_at) {
        return communityJson({ error: "Bạn cần xác nhận email trước khi đăng nhập.", code: "EMAIL_VERIFICATION_REQUIRED" }, 403, request);
      }
      const token = await createCommunitySession(db, row.id);
      return communityJson({ member: safeCommunityMember(row) }, 200, request, { "Set-Cookie": communityCookie(token) });
    }

    if (route === "logout" && request.method === "POST") {
      const token = readCommunityCookie(request);
      if (token) await db.prepare("DELETE FROM community_sessions WHERE token_hash = ?").bind(await sha256Base64Url(token)).run();
      return communityJson({ ok: true }, 200, request, { "Set-Cookie": communityCookie("", 0) });
    }

    if (route === "me" && request.method === "GET") {
      const row = await communityMemberFromRequest(request, db);
      return communityJson({ member: safeCommunityMember(row) }, 200, request);
    }

    // Authenticated, read-only profile data. Never return password hashes, session
    // tokens, OAuth tokens, salts, or provider credentials to the browser.
    if (route === "account" && request.method === "GET") {
      const member = await communityMemberFromRequest(request, db);
      if (!member) return communityJson({ error: "Authentication required to view account details." }, 401, request);
      const account = await db.prepare(
        "SELECT id, username, email, display_name, created_at, email_verified_at " +
        "FROM community_members WHERE id = ? LIMIT 1"
      ).bind(member.id).first();
      if (!account) return communityJson({ error: "Account not found." }, 404, request);
      const providerResult = await db.prepare(
        "SELECT provider FROM community_oauth_accounts WHERE member_id = ? ORDER BY provider"
      ).bind(member.id).all();
      const linkedProviders = [...new Set((providerResult.results || []).map((item) => String(item.provider)))];
      const email = String(account.email || "");
      return communityJson({
        account: {
          id: account.id,
          username: account.username,
          displayName: account.display_name,
          email: email.endsWith("@social.invalid") ? null : email,
          emailVerified: Boolean(account.email_verified_at),
          createdAt: account.created_at,
          linkedProviders,
        },
      }, 200, request);
    }

    if (route === "messages" && request.method === "GET") {
      const member = await communityMemberFromRequest(request, db);
      if (!member) return communityJson({ error: "Hãy đăng nhập để xem phòng thảo luận." }, 401, request);
      const topic = String(url.searchParams.get("topic") || "");
      if (!Object.hasOwn(COMMUNITY_TOPICS, topic)) return communityJson({ error: "Chủ đề thảo luận không hợp lệ." }, 400, request);
      const result = await db.prepare(`SELECT cm.id, cm.topic, cm.body, cm.created_at, m.username, m.display_name, cm.member_id
        FROM community_messages cm JOIN community_members m ON m.id = cm.member_id
        WHERE cm.topic = ? ORDER BY cm.created_at DESC LIMIT 50`).bind(topic).all();
      const messages = (result.results || []).reverse().map((row) => ({ id: row.id, topic: row.topic, body: row.body, createdAt: row.created_at, username: row.username, displayName: row.display_name, own: row.member_id === member.id }));
      return communityJson({ topic, topicLabel: COMMUNITY_TOPICS[topic], messages }, 200, request);
    }

    if (route === "messages" && request.method === "POST") {
      const member = await communityMemberFromRequest(request, db);
      if (!member) return communityJson({ error: "Hãy đăng nhập trước khi gửi tin nhắn." }, 401, request);
      const parsed = await readJsonPayload(request, 3000);
      if (!parsed.ok) return communityJson({ error: parsed.error }, parsed.status, request);
      const payload = parsed.value;
      const topic = String(payload.topic || "");
      const body = String(payload.body || "").trim();
      if (!Object.hasOwn(COMMUNITY_TOPICS, topic)) return communityJson({ error: "Chủ đề thảo luận không hợp lệ." }, 400, request);
      if (!body || body.length > 800) return communityJson({ error: "Tin nhắn cần từ 1 đến 800 ký tự." }, 400, request);
      if (!await communityRateLimit(db, `message:${member.id}`, 8, 60 * 1000)) return communityJson({ error: "Bạn đang gửi tin quá nhanh. Hãy chờ một phút rồi thử lại." }, 429, request);
      const id = crypto.randomUUID();
      await db.prepare("INSERT INTO community_messages (id, topic, member_id, body, created_at) VALUES (?, ?, ?, ?, ?)").bind(id, topic, member.id, body, now).run();
      return communityJson({ message: { id, topic, body, createdAt: now, username: member.username, displayName: member.display_name, own: true } }, 201, request);
    }

    const deleteMatch = route.match(/^messages\/([0-9a-f-]{36})$/i);
    if (deleteMatch && request.method === "DELETE") {
      const member = await communityMemberFromRequest(request, db);
      if (!member) return communityJson({ error: "Hãy đăng nhập để thực hiện thao tác này." }, 401, request);
      const result = await db.prepare("DELETE FROM community_messages WHERE id = ? AND member_id = ?").bind(deleteMatch[1], member.id).run();
      if (!result.meta?.changes) return communityJson({ error: "Không tìm thấy tin nhắn hoặc bạn không có quyền xóa." }, 404, request);
      return communityJson({ ok: true }, 200, request);
    }

    return communityJson({ error: "Không tìm thấy API cộng đồng." }, 404, request);
  } catch (error) {
    // Never log credentials, request bodies, cookies, email addresses or IP addresses.
    // Keep enough sanitized context to diagnose future production failures.
    const failedRoute = new URL(request.url).pathname.replace(/^\/api\/community\/?/, "").slice(0, 64);
    console.error("community_api_error", {
      route: failedRoute || "root",
      method: request.method,
      errorName: error instanceof Error ? error.name : "UnknownError",
      errorMessage: error instanceof Error ? String(error.message).slice(0, 160) : "Non-Error throwable",
    });
    return communityJson({ error: "Tạm thời không xử lý được yêu cầu cộng đồng. Vui lòng thử lại sau." }, 500, request);
  }
}

const CANONICAL_SITE_URL = "https://ai-thuc-chien-blog.manhdungub.workers.dev/";
const ORGANIZATION_LOGO_URL = "https://ai-thuc-chien-blog.manhdungub.workers.dev/logo.svg";
const STAGING_WORKER_HOST = "ai-thuc-chien-blog-auth-app-preview.manhdungub.workers.dev";

const ORGANIZATION_LOGO_SVG = `<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 64 64" role="img" aria-labelledby="logo-title">
<title id="logo-title">AI Thực Chiến</title>
<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#a99bff"/><stop offset="1" stop-color="#77e8d1"/></linearGradient></defs>
<rect width="64" height="64" rx="16" fill="#0b1020"/><rect x="4" y="4" width="56" height="56" rx="13" fill="url(#g)"/>
<path d="M17 43 27 20h10l10 23h-8l-2.1-5.4H27L25 43Zm12.4-11.5h5.2L32 24z" fill="#0b1020"/>
</svg>`;

function createOrganizationLogoResponse(method = "GET") {
  return new Response(method === "HEAD" ? null : ORGANIZATION_LOGO_SVG, {
    status: 200,
    headers: {
      "Content-Type": "image/svg+xml; charset=utf-8",
      "Cache-Control": "no-store, max-age=0",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

function organizationLogoUrlForRequest(requestUrl) {
  return requestUrl.hostname === STAGING_WORKER_HOST
    ? "https://" + STAGING_WORKER_HOST + "/logo.svg"
    : ORGANIZATION_LOGO_URL;
}

function visitStructuredDataNodes(value, visitor) {
  if (Array.isArray(value)) {
    let changed = false;
    for (const item of value) changed = visitStructuredDataNodes(item, visitor) || changed;
    return changed;
  }
  if (!value || typeof value !== "object") return false;
  let changed = visitor(value) === true;
  for (const child of Object.values(value)) {
    if (child && typeof child === "object") changed = visitStructuredDataNodes(child, visitor) || changed;
  }
  return changed;
}

function patchOrganizationLogoInHtml(html, logoUrl = ORGANIZATION_LOGO_URL) {
  let changedAny = false;
  const patchedHtml = html.replace(/<script\b[^>]*type=["']application\/ld\+json["'][^>]*>[\s\S]*?<\/script>/gi, (block) => {
    const openingEnd = block.indexOf(">");
    const closingStart = block.toLowerCase().lastIndexOf("</script>");
    if (openingEnd < 0 || closingStart <= openingEnd) return block;
    let schema;
    try {
      schema = JSON.parse(block.slice(openingEnd + 1, closingStart));
    } catch (_error) {
      return block;
    }
    const changedThisBlock = visitStructuredDataNodes(schema, (node) => {
      const types = Array.isArray(node["@type"]) ? node["@type"] : [node["@type"]];
      if (types.includes("Organization") && node.url === CANONICAL_SITE_URL && node.logo !== logoUrl) {
        node.logo = logoUrl;
        return true;
      }
      return false;
    });
    if (!changedThisBlock) return block;
    changedAny = true;
    return block.slice(0, openingEnd + 1) + JSON.stringify(schema) + block.slice(closingStart);
  });
  return { html: patchedHtml, changed: changedAny };
}

async function withOrganizationLogoSchema(response, logoUrl = ORGANIZATION_LOGO_URL) {
  const contentType = (response.headers.get("Content-Type") || "").toLowerCase();
  if (!response.ok || !contentType.includes("text/html") || !response.body) return response;
  let html;
  try {
    html = await response.text();
  } catch (_error) {
    return new Response(null, { status: 502, headers: { "Cache-Control": "no-store, max-age=0" } });
  }
  const patched = patchOrganizationLogoInHtml(html, logoUrl);
  const headers = new Headers(response.headers);
  headers.delete("Content-Length");
  headers.delete("Content-Encoding");
  if (patched.changed) {
    headers.delete("ETag");
    headers.delete("Last-Modified");
    headers.set("Cache-Control", "no-store, max-age=0");
  }
  return new Response(patched.html, { status: response.status, statusText: response.statusText, headers });
}

function inspectOrganizationLogoSchema(html, logoUrl = ORGANIZATION_LOGO_URL) {
  const result = { organization_logo_present: false, article_publisher_logo_present: false };
  const scripts = [...html.matchAll(/<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
  for (const match of scripts) {
    let schema;
    try {
      schema = JSON.parse(match[1]);
    } catch (_error) {
      continue;
    }
    const nodes = [];
    const collectNodes = (value) => {
      if (Array.isArray(value)) {
        for (const item of value) collectNodes(item);
        return;
      }
      if (!value || typeof value !== "object") return;
      nodes.push(value);
      for (const child of Object.values(value)) collectNodes(child);
    };
    collectNodes(schema);
    for (const node of nodes) {
      const types = Array.isArray(node["@type"]) ? node["@type"] : [node["@type"]];
      if (types.includes("Organization") && node.url === CANONICAL_SITE_URL && node.logo === logoUrl) {
        result.organization_logo_present = true;
      }
      if (types.includes("BlogPosting")) {
        const publisher = node.publisher;
        const publisherTypes = Array.isArray(publisher?.["@type"]) ? publisher["@type"] : [publisher?.["@type"]];
        if (publisherTypes.includes("Organization") &&
            publisher.url === CANONICAL_SITE_URL && publisher.logo === logoUrl) {
          result.article_publisher_logo_present = true;
        }
      }
    }
  }
  return result;
}
async function probePageStructuredData(pathname, logoUrl = ORGANIZATION_LOGO_URL) {
  const url = new URL(pathname, "https://ai-thuc-chien-blog.pages.dev");
  const upstream = await fetch(url.toString(), { headers: { Accept: "text/html" }, redirect: "follow" });
  const transformed = await withOrganizationLogoSchema(upstream, logoUrl);
  if (!transformed.ok || !(transformed.headers.get("Content-Type") || "").toLowerCase().includes("text/html")) {
    return { ok: false, organization_logo_present: false, article_publisher_logo_present: false };
  }
  const html = await transformed.text();
  return { ok: true, ...inspectOrganizationLogoSchema(html, logoUrl) };
}

function resolveAssetRequest(request) {
  const url = new URL(request.url);
  // With html_handling="none", explicitly map the site root to its index file.
  // Canonical article URLs are extensionless while the deployed files are .html.
  // Rewrite only safe GET/HEAD requests; leave mutations and all other paths untouched.
  if ((request.method === "GET" || request.method === "HEAD") && url.pathname === "/") {
    url.pathname = "/index.html";
    return new Request(url, request);
  }
  if (
    (request.method === "GET" || request.method === "HEAD") &&
    /^\/articles\/[a-z0-9-]+$/i.test(url.pathname)
  ) {
    url.pathname += ".html";
    return new Request(url, request);
  }
  return request;
}

export default {
  async fetch(request, env) {
    try {
      const requestUrl = new URL(request.url);
      const pathname = requestUrl.pathname;
      const organizationLogoUrl = organizationLogoUrlForRequest(requestUrl);
      // Canonical article URLs are extensionless. Route legacy .html article URLs
      // to the clean path before requesting Pages; some Pages redirect/fallback
      // handling can otherwise turn an unknown .html slug into the homepage.
      if (
        (request.method === "GET" || request.method === "HEAD") &&
        /^\/articles\/[a-z0-9-]+\.html$/i.test(pathname)
      ) {
        const canonicalUrl = new URL(request.url);
        canonicalUrl.pathname = canonicalUrl.pathname.replace(/\.html$/i, "");
        return withSecurityHeaders(new Response(null, {
          status: 301,
          headers: {
            "Location": canonicalUrl.toString(),
            "Cache-Control": "no-store, max-age=0",
            "Pragma": "no-cache",
          },
        }), request);
      }
      // Serve the Organization logo directly from this Worker. The external
      // Pages fallback may not have the asset yet; JSON-LD must never point to a 404.
      if ((request.method === "GET" || request.method === "HEAD") && pathname === "/logo.svg") {
        return withSecurityHeaders(createOrganizationLogoResponse(request.method), request);
      }
      // Keep direct auth URLs useful on mobile and desktop: the form lives on the
      // homepage, so preserve existing campaign parameters and select its mode.
      if ((request.method === "GET" || request.method === "HEAD") &&
          (pathname === "/login" || pathname === "/register")) {
        const authUrl = new URL(request.url);
        authUrl.pathname = "/";
        authUrl.searchParams.set("mode", pathname.slice(1));
        authUrl.hash = "cong-dong";
        return withSecurityHeaders(new Response(null, {
          status: 302,
          headers: {
            "Location": authUrl.toString(),
            "Cache-Control": "no-store, max-age=0",
            "Pragma": "no-cache",
          },
        }), request);
      }
      // Keep the publicly reachable test environment out of search indexing.
      if (requestUrl.hostname === "ai-thuc-chien-blog-auth-app-preview.manhdungub.workers.dev" &&
          (request.method === "GET" || request.method === "HEAD") && pathname === "/robots.txt") {
        const robots = "User-agent: *\nDisallow: /\n";
        return withSecurityHeaders(new Response(request.method === "HEAD" ? null : robots, {
          status: 200,
          headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store, max-age=0" },
        }), request);
      }
      // Serve all auth-sensitive static assets from the same reviewed source snapshot on staging.
      if ((request.method === "GET" || request.method === "HEAD") && pathname === "/styles.css") {
        return withSecurityHeaders(new Response(request.method === "HEAD" ? null : PREVIEW_STYLES_CSS, {
          status: 200,
          headers: {
            "Content-Type": "text/css; charset=utf-8",
            "Cache-Control": "no-store, max-age=0",
          },
        }), request);
      }
      // Serve the preview-specific frontend script without changing the live Pages copy.
      if ((request.method === "GET" || request.method === "HEAD") && pathname === "/script.js") {
        return withSecurityHeaders(new Response(request.method === "HEAD" ? null : PREVIEW_FRONTEND_SCRIPT, {
          status: 200,
          headers: {
            "Content-Type": "application/javascript; charset=utf-8",
            "Cache-Control": "no-store, max-age=0",
          },
        }), request);
      }
      // Read-only staging diagnostics are available only on the dedicated preview hostname.
      // Never return secrets, relay URLs, member data, or connection values from this route.
      if (requestUrl.hostname === STAGING_WORKER_HOST && pathname === "/__staging/seo-schema" && request.method === "GET") {
        try {
          const [home, article] = await Promise.all([
            probePageStructuredData("/", organizationLogoUrl),
            probePageStructuredData("/articles/bat-dau-voi-ai.html", organizationLogoUrl),
          ]);
          // This checks the exact response factory used by /logo.svg; it does not
          // claim to be an independent wire-level HTTP request (self-fetching a Worker
          // can be routed differently by the platform).
          const logoResponse = createOrganizationLogoResponse("GET");
          const logoContentType = (logoResponse.headers.get("Content-Type") || "").toLowerCase();
          const logoBody = await logoResponse.clone().text();
          const logoBodyValid = /<svg\b/i.test(logoBody) && /width="512"\s+height="512"/i.test(logoBody);
          const logoAssetProbe = {
            ok: logoResponse.status === 200 && logoContentType.includes("image/svg+xml") && logoBodyValid,
            status: logoResponse.status,
            content_type: logoResponse.headers.get("Content-Type"),
            body_valid: logoBodyValid,
          };
          const result = {
            ok: home.ok && article.ok && home.organization_logo_present && article.article_publisher_logo_present && logoAssetProbe.ok,
            environment: "staging",
            homepage_organization_logo_present: home.organization_logo_present,
            article_publisher_logo_present: article.article_publisher_logo_present,
            logo_asset_probe_ok: String(logoAssetProbe.ok),
            logo_asset_response_status: String(logoAssetProbe.status ?? "null"),
            logo_asset_response_content_type: logoAssetProbe.content_type || "null",
            logo_asset_response_body_valid: String(logoAssetProbe.body_valid),
            logo_url: organizationLogoUrl,
          };
          return withSecurityHeaders(new Response(JSON.stringify(result), {
            status: 200,
            headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store, max-age=0" },
          }), request);
        } catch (_error) {
          return withSecurityHeaders(new Response(JSON.stringify({
            ok: false, environment: "staging",
            homepage_organization_logo_present: false,
            article_publisher_logo_present: false,
          }), {
            status: 502,
            headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store, max-age=0" },
          }), request);
        }
      }
      if (requestUrl.hostname === "ai-thuc-chien-blog-auth-app-preview.manhdungub.workers.dev" &&
          pathname === "/__staging/status" && request.method === "GET") {
        const databaseReady = Boolean(env.DB && typeof env.DB.prepare === "function");
        let schemaReady = false;
        if (databaseReady) {
          try {
            const tableResult = await env.DB.prepare("SELECT name FROM sqlite_master WHERE type = 'table'").all();
            const tableNames = new Set((tableResult.results || []).map((row) => row.name));
            const requiredTables = ["community_members", "community_sessions", "community_messages", "community_rate_limits", "community_email_verification_tokens", "community_password_reset_tokens", "community_oauth_accounts"];
            const columnResult = await env.DB.prepare("PRAGMA table_info(community_members)").all();
            const columnNames = new Set((columnResult.results || []).map((row) => row.name));
            schemaReady = requiredTables.every((name) => tableNames.has(name)) &&
              columnNames.has("email_verified_at");
          } catch (_schemaError) {
            schemaReady = false;
          }
        }
        let emailSendingEnabled = false;
        try {
          const relay = new URL(String(env.COMMUNITY_EMAIL_RELAY_URL || "").trim());
          const secret = String(env.COMMUNITY_EMAIL_RELAY_SECRET || "");
          emailSendingEnabled = relay.protocol === "https:" && relay.hostname === "script.google.com" &&
            relay.pathname.startsWith("/macros/s/") && relay.pathname.endsWith("/exec") && secret.length >= 32;
        } catch (_relayConfigurationError) {
          emailSendingEnabled = false;
        }
        const payload = {
          ok: databaseReady && schemaReady,
          environment: "staging",
          database_ready: databaseReady,
          schema_ready: schemaReady,
          email_sending_enabled: emailSendingEnabled,
          registration_ready: databaseReady && schemaReady && emailSendingEnabled,
        };
        return withSecurityHeaders(new Response(JSON.stringify(payload), {
          status: databaseReady && schemaReady ? 200 : 503,
          headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" },
        }), request);
      }
      // resolveAssetRequest maps / to /index.html internally, keeping the public URL canonical.
      if (pathname === "/api/chat") return withSecurityHeaders(await handleChat(request, env), request);
      if (pathname === "/api/community" || pathname.startsWith("/api/community/")) {
        return withSecurityHeaders(await handleCommunityApi(request, env), request);
      }
      if (requestUrl.hostname === STAGING_WORKER_HOST &&
          (request.method === "GET" || request.method === "HEAD") &&
          (pathname === "/" || pathname === "/index.html")) {
        const previewHtml = new Response(request.method === "HEAD" ? null : PREVIEW_INDEX_HTML, {
          status: 200,
          headers: {
            "Content-Type": "text/html; charset=utf-8",
            "Cache-Control": "no-store, max-age=0",
          },
        });
        return withSecurityHeaders(await withOrganizationLogoSchema(previewHtml, organizationLogoUrl), request);
      }
      const isHomepageRead = (request.method === "GET" || request.method === "HEAD") && pathname === "/";
      if (isHomepageRead) {
        // Prefer the separately verified Pages copy for the public homepage. This
        // bypasses a stale/misrouted Worker asset response while keeping the visitor
        // on the canonical Worker origin so same-origin APIs still work.
        try {
          const pagesUrl = new URL(request.url);
          pagesUrl.hostname = "ai-thuc-chien-blog.pages.dev";
          // The browser must retain ?verify=… so its frontend can submit the token,
          // but never forward that bearer token to the separate Pages origin.
          pagesUrl.searchParams.delete("verify");
          const pagesHeaders = new Headers();
          for (const name of ["Accept", "Accept-Language", "User-Agent"]) {
            const value = request.headers.get(name);
            if (value) pagesHeaders.set(name, value);
          }
          const pagesResponse = await fetch(pagesUrl.toString(), {
            method: request.method,
            headers: pagesHeaders,
            redirect: "follow",
          });
          if (pagesResponse.ok && (pagesResponse.headers.get("Content-Type") || "").toLowerCase().includes("text/html")) {
            let pagesLooksNotFound = false;
            if (request.method === "GET") {
              const pagesBody = await pagesResponse.clone().text();
              pagesLooksNotFound = /LỖI\s*404|KHÔNG TÌM THẤY TRANG|Có vẻ đường dẫn đã đi lạc/i.test(pagesBody);
            }
            if (!pagesLooksNotFound) return withSecurityHeaders(await withOrganizationLogoSchema(pagesResponse, organizationLogoUrl), request);
          }
        } catch (_pagesPrimaryError) {
          // Try the Worker asset binding below if the Pages homepage is unreachable.
        }
      }
      const assetRequest = resolveAssetRequest(request);
      const assetUrl = new URL(assetRequest.url);
      // The isolated auth preview has no Workers Assets binding. Proxy static GET/HEAD
      // requests to the independently hosted Pages copy instead of touching production.
      assetUrl.hostname = "ai-thuc-chien-blog.pages.dev";
      const assetHeaders = new Headers();
      for (const name of ["Accept", "Accept-Language", "User-Agent"]) {
        const value = request.headers.get(name);
        if (value) assetHeaders.set(name, value);
      }
      const assetResponse = await fetch(assetUrl.toString(), {
        method: request.method,
        headers: assetHeaders,
        redirect: "follow",
      });
      // Unknown article slugs must stay 404s; redirecting them to the homepage hides
      // broken links from users and search engines.
      const isArticleRoute = /^\/articles\/[a-z0-9-]+(?:\.html)?$/i.test(pathname);
      let articleLooksNotFound = false;
      if (
        isArticleRoute &&
        (request.method === "GET" || request.method === "HEAD") &&
        assetResponse.status === 200 &&
        (assetResponse.headers.get("Content-Type") || "").toLowerCase().includes("text/html")
      ) {
        const finalPath = assetResponse.url ? new URL(assetResponse.url).pathname : "";
        articleLooksNotFound = finalPath === "/";
        if (!articleLooksNotFound && request.method === "GET") {
          try {
            const articleBody = await assetResponse.clone().text();
            articleLooksNotFound = /LỖI\s*404|KHÔNG TÌM THẤY TRANG|Có vẻ đường dẫn đã đi lạc/i.test(articleBody);
          } catch (_articleBodyError) {
            articleLooksNotFound = false;
          }
        }
      }
      if (isArticleRoute && (assetResponse.status === 404 || articleLooksNotFound)) {
        const headers = new Headers(assetResponse.headers);
        headers.set("Cache-Control", "no-store, max-age=0");
        headers.set("Pragma", "no-cache");
        return withSecurityHeaders(new Response(request.method === "HEAD" ? null : assetResponse.body, {
          status: 404,
          statusText: "Not Found",
          headers,
        }), request);
      }

      // Other unknown page routes retain the existing homepage-recovery behavior.
      // Do not redirect APIs, articles, or missing static files such as CSS/images.
      const isPageLikePath = pathname !== "/" && !pathname.startsWith("/api/") &&
        !isArticleRoute && !/\.(?!html?$)[a-z0-9]{1,10}$/i.test(pathname);
      const isHtmlNotFound = (request.method === "GET" || request.method === "HEAD") &&
        isPageLikePath && assetResponse.status === 404 &&
        (assetResponse.headers.get("Content-Type") || "").toLowerCase().includes("text/html");
      if (isHtmlNotFound) {
        const homeUrl = new URL(request.url);
        homeUrl.pathname = "/";
        homeUrl.hash = "";
        return withSecurityHeaders(new Response(null, {
          status: 302,
          headers: {
            "Location": homeUrl.toString(),
            "Cache-Control": "no-store, max-age=0",
            "Pragma": "no-cache",
          },
        }), request);
      }
      let looksLikeBrandedNotFound = false;
      if (
        isHomepageRead &&
        assetResponse.status === 200 &&
        (assetResponse.headers.get("Content-Type") || "").toLowerCase().includes("text/html")
      ) {
        // Some asset/fallback layers can return a branded 404 document with HTTP 200.
        // Inspect a clone so the original response remains available if Pages cannot be reached.
        try {
          const body = await assetResponse.clone().text();
          looksLikeBrandedNotFound = /LỖI\s*404|KHÔNG TÌM THẤY TRANG|Có vẻ đường dẫn đã đi lạc/i.test(body);
        } catch (_bodyCheckError) {
          looksLikeBrandedNotFound = false;
        }
      }
      if (isHomepageRead && (assetResponse.status === 404 || assetResponse.status >= 500 || looksLikeBrandedNotFound)) {
        // Keep the canonical Worker URL available if its asset binding temporarily
        // returns a not-found/server error; Pages is the independently verified static fallback.
        try {
          const fallbackUrl = new URL(request.url);
          fallbackUrl.hostname = "ai-thuc-chien-blog.pages.dev";
          const fallbackHeaders = new Headers();
          for (const name of ["Accept", "Accept-Language", "User-Agent"]) {
            const value = request.headers.get(name);
            if (value) fallbackHeaders.set(name, value);
          }
          const fallbackResponse = await fetch(fallbackUrl.toString(), {
            method: request.method,
            headers: fallbackHeaders,
            redirect: "follow",
          });
          if (fallbackResponse.ok && (fallbackResponse.headers.get("Content-Type") || "").toLowerCase().includes("text/html")) {
            return withSecurityHeaders(await withOrganizationLogoSchema(fallbackResponse, organizationLogoUrl), request);
          }
        } catch (_fallbackError) {
          // Preserve the original Worker asset response if the fallback cannot be reached.
        }
      }
      return withSecurityHeaders(await withOrganizationLogoSchema(assetResponse, organizationLogoUrl), request);
    } catch (_error) {
      const failure = new Response("Internal Server Error\n", {
        status: 500,
        headers: {
          "Content-Type": "text/plain; charset=utf-8",
          "Cache-Control": "no-store",
        },
      });
      return withSecurityHeaders(failure, request);
    }
  },
};
